48	/// The checker binaries a `tsc_path` may name, the builds whose protocol this backend was traced against (the built-in
49	/// checker is pinned in `Cargo.toml` instead): the `typescript` 7.1 series, from `7.1.0-beta` on, and the `tsrs` builds
50	/// listed exactly (`<tsrs version>-ts<typescript version>`), each only while its TypeScript part is in the series above.
51	/// The protocol has no version handshake, so the package's `package.json` version and the initialize call that follows
52	/// the spawn are the whole check; a build that fails either takes the structural result with one warning.
53	pub const SUPPORTED_VERSIONS: &[&str] = &["7.1", "0.23.0-ts7.1.0-beta"];
54	
55	/// How many files are asked about at once. The checker answers requests one at a time; this keeps it from idling
56	/// between them.
57	const FILES_IN_FLIGHT: usize = 16;
58	
59	/// A component the structural pass found.
60	pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;
61	
62	/// The components of `output`, in output order.
63	pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
64	    output
65	        .components
66	        .iter()
67	        .map(|(key, entry)| Target {
68	            key: key.clone(),
69	            file_path: entry.file_path.clone(),
70	            display_name: entry.display_name.clone(),
71	            exports: entry.exports.clone(),
72	            described: entry
73	                .props
74	                .values()
75	                .filter(|prop| !prop.description.is_empty())
76	                .map(|prop| prop.name.clone())
77	                .collect(),
78	            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
79	            react_wanted: Some(Default::default()),
80	        })
81	        .collect()
82	}
