84	/// One whole-project request to the checker: the components to answer for, and which checker to ask. Built with
85	/// [`SemanticRequest::new`] and answered by [`resolve`].
86	#[derive(Debug, Clone)]
87	pub struct SemanticRequest {
88	    /// Where the checker finds `node_modules`: its working directory.
89	    pub project_root: Utf8PathBuf,
90	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
91	    pub tsconfig: Option<Utf8PathBuf>,
92	    /// A checker binary to run as a `tsc --api` process (`typescript@7.1`'s `tsc`, or `tsrs`) instead of the built-in
93	    /// checker.
94	    pub tsc_path: Option<Utf8PathBuf>,
95	    /// The components to ask about.
96	    pub targets: Vec<Target>,
97	    /// Bound on each request, and on a checker process's start-up handshake.
98	    pub request_timeout: Duration,
99	    /// The versions a checker binary's `package.json` may declare; one that is not among them is a start-up failure.
100	    /// The built-in checker is pinned and not checked.
101	    pub expected_versions: &'static [&'static str],
102	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
103	    pub record_to: Option<Utf8PathBuf>,
104	    /// Environment for a checker process; the tests use it to pick a replay scenario.
105	    pub extra_env: Vec<(String, String)>,
106	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
107	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
108	    pub reverse_queries: bool,
109	}
110	
111	impl SemanticRequest {
112	    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
113	    /// tsconfig or explicit `tsc` path.
114	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
115	        Self {
116	            project_root,
117	            tsconfig: None,
118	            tsc_path: None,
119	            targets,
120	            request_timeout: Duration::from_secs(60),
121	            expected_versions: SUPPORTED_VERSIONS,
122	            record_to: None,
123	            extra_env: Vec::new(),
124	            reverse_queries: false,
125	        }
126	    }
127	}
128	
129	/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
130	/// not be called from inside one.
131	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
132	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
133	        Ok(runtime) => runtime,
134	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
135	    };
136	    runtime.block_on(run(request))
137	}
