139	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
140	/// the checker cannot be asked about.
141	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
142	    let mut outcome = SemanticOutcome::default();
143	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
144	    let mut order: Vec<&Utf8Path> = Vec::new();
145	    for target in &request.targets {
146	        if target.exports.is_empty() {
147	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
148	            continue;
149	        }
150	        let group = by_file.entry(target.file_path.as_path()).or_default();
151	        if group.is_empty() {
152	            order.push(target.file_path.as_path());
153	        }
154	        group.push(target);
155	    }
156	    (outcome, by_file, order)
157	}
158	
159	/// The checker `request` names: its `tsc_path` as a process, else the built-in one.
160	async fn start_checker(request: &SemanticRequest) -> Result<Backend, String> {
161	    Backend::start(Start {
162	        project_root: &request.project_root,
163	        tsc_path: request.tsc_path.as_deref(),
164	        expected_versions: request.expected_versions,
165	        timeout: request.request_timeout,
166	        extra_env: &request.extra_env,
167	    })
168	    .await
169	}
170	
171	async fn run(request: SemanticRequest) -> SemanticOutcome {
172	    if request.targets.iter().all(|target| target.exports.is_empty()) {
173	        return group_by_file(&request).0;
174	    }
175	    let checker = match start_checker(&request).await {
176	        Ok(checker) => checker,
177	        Err(reason) => return SemanticOutcome::unavailable(reason),
178	    };
179	    let outcome = answer_with(&checker, &request).await;
180	    checker.shutdown().await;
181	    outcome
182	}
183	
184	/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
185	fn root_files(request: &SemanticRequest) -> Vec<String> {
186	    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
187	}
188	
189	/// Answers the request's targets with a checker that is already running: one program rooted at their files, released
190	/// once they are answered.
191	async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
192	    let files = root_files(request);
193	    if files.is_empty() {
194	        return group_by_file(request).0;
195	    }
196	    let started = std::time::Instant::now();
197	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
198	    let opened =
199	        Rpc::open(checker.client(), request.request_timeout, tsconfig, &files, request.record_to.is_some()).await;
200	    let rpc = match opened {
201	        Ok(rpc) => Arc::new(rpc),
202	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
203	    };
204	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, "semantic program built");
205	    let answered = answer_on(&rpc, request, &files).await;
206	    rpc.release().await;
207	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
208	}
209	
210	/// Answers the request's targets on a snapshot whose program is rooted at `files` ([`root_files`]). The snapshot is
211	/// left as it is, for the caller to keep or release.
212	async fn answer_on(rpc: &Arc<Rpc>, request: &SemanticRequest, files: &[String]) -> Result<SemanticOutcome, CallError> {
213	    let (mut outcome, by_file, order) = group_by_file(request);
214	    let mut answered = session(rpc, request, files, &by_file, &order).await?;
215	    outcome.components.append(&mut answered.components);
216	    outcome.fallbacks.append(&mut answered.fallbacks);
217	    Ok(outcome)
218	}
219	
220	async fn session(
221	    rpc: &Arc<Rpc>,
222	    request: &SemanticRequest,
223	    files: &[String],
224	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
225	    order: &[&Utf8Path],
226	) -> Result<SemanticOutcome, CallError> {
227	    let started = std::time::Instant::now();
228	    let converter = Converter::new(rpc.clone(), request.reverse_queries);
229	    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
230	    let interner = Arc::new(PropInterner::default());
231	
232	    let mut tasks = JoinSet::new();
233	    for file in order {
234	        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
235	        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
236	        tasks.spawn(async move {
237	            let _permit = limit.acquire().await;
238	            answer_file(&rpc, &converter, &interner, targets).await
239	        });
240	    }
241	
242	    let mut outcome = SemanticOutcome::default();
243	    let mut generic = Vec::new();
244	    let mut failure = None;
245	    while let Some(joined) = tasks.join_next().await {
246	        match joined {
247	            Ok(Ok((mut answered, mut instantiations))) => {
248	                outcome.components.append(&mut answered.components);
249	                outcome.fallbacks.append(&mut answered.fallbacks);
250	                generic.append(&mut instantiations);
251	            }
252	            Ok(Err(error)) => {
253	                failure = Some(error);
254	                tasks.abort_all();
255	            }
256	            // A panic inside a worker must not silently leave its components structural.
257	            Err(joined) if joined.is_panic() => {
258	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
259	                tasks.abort_all();
260	            }
261	            // A cancelled task is one this loop aborted after a failure.
262	            Err(_cancelled) => {}
263	        }
264	    }
265	    if let Some(error) = failure {
266	        return Err(error);
267	    }
268	    if !generic.is_empty() {
269	        let mut instantiated =
270	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
271	        outcome.components.append(&mut instantiated.components);
272	        outcome.fallbacks.append(&mut instantiated.fallbacks);
273	    }
274	
275	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
276	        && let Ok(json) = serde_json::to_string_pretty(&recording)
277	        && let Err(error) = std::fs::write(path, json)
278	    {
279	        tracing::warn!("could not write the recording to {path}: {error}");
280	    }
281	    tracing::debug!(
282	        requests = ?rpc.calls(),
283	        files = files.len(),
284	        type_memo = ?converter.memo_stats(),
285	        total_ms = started.elapsed().as_millis() as u64,
286	        "semantic backend finished"
287	    );
288	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
289	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
290	    Ok(outcome)
291	}
292	
293	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
294	    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
295	}
296	
297	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
298	/// generic components come back apart, to be answered from their instantiations once every file is done.
299	async fn answer_file(
300	    rpc: &Rpc,
301	    converter: &Converter,
302	    interner: &PropInterner,
303	    targets: Vec<Target>,
304	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
305	    let mut outcome = SemanticOutcome::default();
306	    let mut generic = Vec::new();
307	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
308	    let module = match module_exports(rpc, first.file_path.as_str()).await {
309	        Ok(Some(module)) => module,
310	        Ok(None) | Err(CallError::Rejected(_)) => {
311	            outcome
312	                .fallbacks
313	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
314	            return Ok((outcome, generic));
315	        }
316	        Err(fatal) => return Err(fatal),
317	    };
318	
319	    for target in &targets {
320	        let requests = Arc::new(AtomicU64::new(0));
321	        let started = std::time::Instant::now();
322	        let answered =
323	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
324	        tracing::debug!(
325	            component = %target.display_name,
326	            requests = requests.load(Ordering::Relaxed),
327	            ms = started.elapsed().as_millis() as u64,
328	            "semantic component answered"
329	        );
330	        match answered {
331	            Ok(Answer::Props(component::Props { props, composes })) => {
332	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes });
333	            }
334	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
335	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
336	            Err(CallError::Rejected(message)) => {
337	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
338	            }
339	            Err(fatal) => return Err(fatal),
340	        }
341	    }
342	    Ok((outcome, generic))
343	}
344	
345	/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
346	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
347	    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
348	    let exports = rpc.exports_of_module(&symbol.reference).await?;
349	    Ok(Some(component::Module { symbol, exports }))
350	}
