// Asks a lazy session (the Storybook addon's configuration) for every component of a project one at a time and
// prints the process's resident memory every `step` components. usage: node session_mem.mjs <napi dir> <src> <checker:on|off> [limit]
import { createRequire } from 'node:module'
import { execFileSync } from 'node:child_process'

const [napiDir, src, mode, limitArg] = process.argv.slice(2)
const napi = createRequire(import.meta.url)(napiDir)
const options = {
  srcDirs: [src],
  lazy: true,
  loadDependencies: true,
  collapseInheritedProps: 'none',
  checker: mode === 'on',
  // Wait long enough that each answer is the checker's, as a story asked again would be.
  semanticWaitMs: 60_000,
  semanticWaitEmptyMs: 60_000,
}
const rssMib = () => Number(execFileSync('ps', ['-o', 'rss=', '-p', String(process.pid)]).toString().trim()) / 1024
const id = napi.createSession(options)
const index = JSON.parse(await napi.initializeSessionIndex(id, options))
const keys = Object.keys(index.components).sort()
const limit = Math.min(keys.length, Number(limitArg ?? keys.length))
const started = performance.now()
let peak = rssMib()
for (let i = 0; i < limit; i++) {
  const answers = JSON.parse(napi.sessionComponentAnswers(id, [keys[i]]))
  if (i === 0) console.log('first answer diagnostics:', JSON.stringify(answers[keys[i]]?.diagnostics ?? []).slice(0, 200))
  const rss = rssMib()
  peak = Math.max(peak, rss)
  if ((i + 1) % 100 === 0 || i + 1 === limit) {
    console.log(`${mode} ${i + 1} components: rss ${rss.toFixed(0)} MiB, peak ${peak.toFixed(0)} MiB, ${((performance.now() - started) / 1000).toFixed(1)} s`)
  }
}
napi.closeSession(id)

