131	
132	    /// Sets how long a request for a component with no structural props waits for the checker. A wait at most `wait`
133	    /// gives such a component the same wait as every other.
134	    pub(crate) fn wait_empty(&mut self, wait_empty: Duration) {
135	        self.wait_empty = wait_empty;
136	    }
137	
138	    /// The wait for `answer`. Nobody waits for a background request: its answer is kept for the request that follows.
139	    /// Someone does for an interactive one, and longer when the structural pass found no props, since there is nothing
140	    /// to show before the checker answers. Any prop, even a degraded one, is an answer worth showing at the short wait.
141	    fn wait_for(&self, answer: &ComponentAnswer, priority: Priority) -> Duration {
142	        match (priority, answer.entry.props.is_empty()) {
143	            (Priority::Background, _) => Duration::ZERO,
144	            (Priority::Interactive, true) => self.wait_empty.max(self.wait),
145	            (Priority::Interactive, false) => self.wait,
146	        }
147	    }
148	
149	    /// Forget every answer, refuse the ones still being waited for, and tell the checker what changed: a source file
150	    /// changed, and the checker's props for any component can depend on it. The next request of each component asks
151	    /// the checker again, after it has been told, rather than joining a request asked before the change.
152	    pub(crate) fn invalidate(&self, change: SourceChange) {
153	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
154	        cache.generation += 1;
155	        cache.answers.clear();
156	        cache.pending.clear();
157	        self.provider.changed(change);
158	    }
159	
160	    /// `answer` with the checker's props, when it has them within the wait `priority` gives it.
161	    pub(crate) fn refine(
162	        &self,
163	        mut answer: ComponentAnswer,
164	        mode: HtmlAttributeMode,
165	        priority: Priority,
166	    ) -> ComponentAnswer {
167	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
168	            let mut hasher = FxHasher::default();
169	            bytes.hash(&mut hasher);
170	            hasher.finish()
171	        });
172	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
173	
174	        let (found, generation) = self.find(cache_key.as_ref(), priority);
175	        let pending = match found {
176	            Found::Cached(cached) => {
177	                self.apply(&mut answer, cached, mode);
178	                return answer;
179	            }
180	            Found::Joined(pending) => pending,
181	            Found::Asking(pending) => {
182	                self.ask(&answer, mode, &pending, cache_key, generation);
183	                pending
184	            }
185	        };
186	
187	        match pending.wait(self.wait_for(&answer, priority)) {
188	            Some(Settled::Answered { answered, once }) => {
189	                for diagnostic in once {
190	                    if !self.warned.swap(true, Ordering::Relaxed) {
191	                        answer.diagnostics.push(diagnostic);
192	                    }
193	                }
194	                self.apply(&mut answer, answered, mode);
195	            }
196	            Some(Settled::Stopped) => {
197	                let mut stopped = Diagnostic::new(
198	                    DiagnosticSeverity::Warning,
199	                    DiagnosticCode::SemanticBackend,
200	                    "the TypeScript checker stopped without answering; the structural props are used",
201	                );
202	                stopped.affects = vec![answer.key.clone()];
203	                answer.diagnostics.push(stopped);
204	            }
205	            None => {
206	                let mut pending = Diagnostic::new(
207	                    DiagnosticSeverity::Info,
208	                    DiagnosticCode::SemanticBackend,
209	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
210	                     replace them on the next request",
211	                );
212	                pending.affects = vec![answer.key.clone()];
213	                answer.diagnostics.push(pending);
214	            }
215	        }
216	        answer
217	    }
218	
219	    /// The kept answer for `key`, else the request in flight for it (raised when someone waits for this one), else a
220	    /// new request this caller makes, registered so the next caller joins it. One lock, so two callers never both ask.
221	    /// A file that could not be read has no key: its request is neither kept nor joined.
222	    fn find(&self, key: Option<&(String, u64)>, priority: Priority) -> (Found, u64) {
223	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
224	        let generation = cache.generation;
225	        if let Some(key) = key {
226	            if let Some(cached) = cache.answers.get(key) {
227	                return (Found::Cached(cached.clone()), generation);
228	            }
229	            if let Some(pending) = cache.pending.get(key) {
230	                match priority {
231	                    Priority::Interactive => pending.priority.raise(),
232	                    Priority::Background => {}
233	                }
234	                return (Found::Joined(pending.clone()), generation);
235	            }
236	        }
237	        let pending = Arc::new(Pending::new(priority));
238	        if let Some(key) = key {
239	            cache.pending.insert(key.clone(), pending.clone());
240	        }
241	        (Found::Asking(pending), generation)
242	    }
243	
244	    /// Asks the checker for `answer`'s component. Its outcome settles `pending` for every caller waiting on it and is
245	    /// kept for the next request, unless the cache was invalidated since `generation`. Called without the cache's lock,
246	    /// since a provider may deliver at once.
247	    fn ask(
248	        &self,
249	        answer: &ComponentAnswer,
250	        mode: HtmlAttributeMode,
251	        pending: &Arc<Pending>,
252	        key: Option<(String, u64)>,
